//! The shell, exercised against real files, a real SQLite store and real
//! sockets on loopback. All input is generated by `pure::synth`.

use std::fs;
use std::io::{Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::time::Duration;

use packetlane::pure::checksum::fnv1a;
use packetlane::pure::synth::demo_run;
use packetlane::shell::ingest::ingest_targets;
use packetlane::shell::server::{Options, Server};
use packetlane::shell::store::{Status, Store};

/// A scratch folder that is removed when the test ends.
struct Scratch(PathBuf);

impl Scratch {
    fn new() -> Scratch {
        static NEXT: AtomicUsize = AtomicUsize::new(0);
        let dir = std::env::temp_dir().join(format!(
            "packetlane-test-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::SeqCst)
        ));
        fs::create_dir_all(&dir).unwrap();
        Scratch(fs::canonicalize(dir).unwrap())
    }

    /// Writes the generated demo run and returns its folder.
    fn demo(&self) -> PathBuf {
        let run = self.0.join("run");
        for file in demo_run(60) {
            let path = run.join(file.rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, file.bytes).unwrap();
        }
        run
    }
}

impl Drop for Scratch {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

fn snapshot(dir: &Path, out: &mut Vec<(PathBuf, u64)>) {
    let mut entries: Vec<_> = fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    entries.sort();
    for path in entries {
        if path.is_dir() {
            snapshot(&path, out);
        } else {
            out.push((path.clone(), fnv1a(&fs::read(&path).unwrap())));
        }
    }
}

fn count(store: &Store, sql: &str) -> i64 {
    store.query_user(sql, 10).unwrap().rows[0][0].int().unwrap()
}

#[test]
fn ingest_finds_the_built_in_faults_and_leaves_the_logs_alone() {
    let scratch = Scratch::new();
    let run = scratch.demo();
    let mut before = Vec::new();
    snapshot(&run, &mut before);

    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    let summary = ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    assert_eq!(summary.files.len(), 7);
    assert!(
        summary.files.iter().all(|f| f.status == Status::Ingested),
        "{:?}",
        summary.files
    );
    assert_eq!(summary.problems, 4);

    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();
    assert_eq!(
        count(&reader, "select count(*) from packets"),
        // Each COSMOS 4 file also opens with its SYSTEM META packet.
        360 + (180 + 1) + 537 + (3 + 1)
    );
    assert_eq!(
        count(
            &reader,
            "select count(*) from findings where kind = 'interleaved'"
        ),
        0
    );
    assert_eq!(
        count(
            &reader,
            "select count(*) from findings where kind = 'hop_missing'"
        ),
        1
    );
    assert_eq!(
        count(
            &reader,
            "select count(*) from findings where kind = 'origins'"
        ),
        0
    );
    assert_eq!(
        count(
            &reader,
            "select count(*) from packets where packet_ns is null and apid != 200"
        ),
        0
    );
    // The ground host's clock runs 250 ms fast and its log is in local time;
    // the configuration corrects both.
    assert_eq!(
        count(
            &reader,
            "select min(log_ns) from log_view where file = 'ground/ground.log'"
        ),
        1_767_225_602_000_000_000
    );
    assert_eq!(
        count(
            &reader,
            "select min(g.receive_ns) - min(a.receive_ns) from packet_view g, packet_view a
             where g.source = 'ground' and a.source = 'bench-a' and g.apid = 100 and a.apid = 100"
        ),
        39_000_000
    );

    // Ingesting again changes nothing.
    let again = ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    assert!(
        again
            .files
            .iter()
            .all(|f| f.status == Status::AlreadyIngested)
    );
    assert_eq!(count(&reader, "select count(*) from packets"), 1082);
    assert_eq!(again.problems, 4);

    // The input folder holds exactly what it held before, byte for byte.
    let mut after = Vec::new();
    snapshot(&run, &mut after);
    assert_eq!(before, after);
}

#[test]
fn a_cut_off_log_is_read_as_far_as_it_goes() {
    let scratch = Scratch::new();
    let run = scratch.demo();
    let log = run.join("ground/downlink.bin");
    let bytes = fs::read(&log).unwrap();
    // Cut into the last packet: past the closing marker the file ends with.
    let cut = packetlane::pure::synth::DEMO_COSMOS5_TAIL + 5;
    fs::write(&log, &bytes[..bytes.len() - cut]).unwrap();
    fs::write(run.join("ground/notes.gz"), [0x1F, 0x8B, 8, 0]).unwrap();

    let mut store = Store::open(&scratch.0.join("store.db")).unwrap();
    let summary = ingest_targets(&mut store, &[run], None, None, None).unwrap();
    let file = |rel: &str| summary.files.iter().find(|f| f.rel == rel).unwrap();
    assert_eq!(file("ground/downlink.bin").status, Status::Ingested);
    assert_eq!(file("ground/downlink.bin").packets, 536);
    assert!(file("ground/downlink.bin").note.contains("Truncated"));
    assert_eq!(file("ground/notes.gz").status, Status::NotReadable);
}

#[test]
fn the_read_only_store_cannot_be_made_to_write() {
    let scratch = Scratch::new();
    let db = scratch.0.join("store.db");
    drop(Store::open(&db).unwrap());
    let reader = Store::open_read_only(&db, Duration::from_secs(5)).unwrap();
    let other = scratch.0.join("other.db");
    for sql in [
        "insert into runs (root) values ('x')".to_string(),
        "delete from runs".to_string(),
        "create table t (x)".to_string(),
        "pragma user_version = 9".to_string(),
        format!("attach database '{}' as other", other.display()),
        format!("vacuum into '{}'", other.display()),
    ] {
        assert!(reader.query_user(&sql, 10).is_err(), "{sql}");
    }
    assert!(!other.exists());
    assert_eq!(count(&reader, "pragma user_version"), 1);
    // A statement that would run forever is stopped by the time budget.
    let endless =
        "with recursive c(x) as (select 1 union all select x + 1 from c) select count(*) from c";
    assert!(reader.query_user(endless, 10).is_err());
}

fn http(port: u16, request: &str) -> (u16, String) {
    let mut stream = TcpStream::connect(("127.0.0.1", port)).unwrap();
    stream.write_all(request.as_bytes()).unwrap();
    let mut response = String::new();
    stream.read_to_string(&mut response).unwrap();
    let status = response
        .split(' ')
        .nth(1)
        .and_then(|s| s.parse().ok())
        .unwrap_or(0);
    let body = response
        .split_once("\r\n\r\n")
        .map_or(String::new(), |(_, b)| b.to_string());
    (status, body)
}

#[test]
fn the_server_refuses_anything_it_should_not_serve() {
    let scratch = Scratch::new();
    let run = scratch.demo();
    let outside = scratch.0.join("outside");
    fs::create_dir_all(&outside).unwrap();
    fs::write(outside.join("secret.log"), "2026-01-01 00:00:00 secret\n").unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(&outside, run.join("way-out")).unwrap();

    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    drop(store);

    let server = Server::bind(Options {
        db,
        roots: vec![run.clone()],
        config: None,
        user_config: None,
        port: 0,
    })
    .unwrap();
    let (port, token) = (server.port(), server.token().to_string());
    std::thread::spawn(move || server.run());

    let get = |target: &str, headers: &str| {
        http(
            port,
            &format!("GET {target} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{headers}\r\n"),
        )
    };
    let auth = format!("X-Packetlane-Token: {token}\r\n");
    let post = |path: &str, body: &str| {
        http(
            port,
            &format!(
                "POST {path} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{auth}Content-Length: {}\r\n\r\n{body}",
                body.len()
            ),
        )
    };

    // What it should serve.
    let (status, page) = get(&format!("/?t={token}"), "");
    assert_eq!(status, 200);
    assert!(page.contains("<canvas"));
    let (status, runs) = get("/api/runs", &auth);
    assert_eq!(status, 200);
    assert!(runs.contains("\"problems\":4"), "{runs}");
    let (status, summary) = get("/api/run?run=1", &auth);
    assert_eq!(status, 200);
    assert!(summary.contains("\"name\":\"PAYLOAD_SCIENCE\""));
    let (status, packet) = get("/api/packet?id=1", &auth);
    assert_eq!(status, 200);
    assert!(
        packet.contains("\"name\":\"SIM_HK\"") && packet.contains("\"label\":\"RUNNING\""),
        "{packet}"
    );
    let (status, density) = get(
        "/api/density?run=1&clock=receive&origin=1767225600000000000&from=0&to=60000000000&buckets=100",
        &auth,
    );
    assert_eq!(status, 200);
    assert!(density.contains("\"total\":1099"), "{density}");

    // Without the token, or with the wrong one.
    assert_eq!(get("/", "").0, 401);
    assert_eq!(get("/?t=0000", "").0, 401);
    assert_eq!(get("/api/runs", "").0, 401);
    assert_eq!(get("/api/runs", "X-Packetlane-Token: 0000\r\n").0, 401);
    // As another site would send it.
    assert_eq!(
        get(
            "/api/runs",
            &format!("{auth}Origin: http://evil.example\r\n")
        )
        .0,
        403
    );
    assert_eq!(
        get(
            "/api/runs",
            &format!("{auth}Sec-Fetch-Site: cross-site\r\n")
        )
        .0,
        403
    );
    let foreign = format!("GET /api/runs HTTP/1.1\r\nHost: evil.example:{port}\r\n{auth}\r\n");
    assert_eq!(http(port, &foreign).0, 403);

    // Paths outside the root, however they are spelled.
    let enc = |p: &Path| p.to_string_lossy().replace('/', "%2F");
    assert_eq!(
        get(&format!("/api/browse?path={}", enc(&run)), &auth).0,
        200
    );
    assert_eq!(
        get(&format!("/api/browse?path={}", enc(&outside)), &auth).0,
        403
    );
    assert_eq!(
        get(
            &format!("/api/browse?path={}%2F..%2Foutside", enc(&run)),
            &auth
        )
        .0,
        403
    );
    assert_eq!(
        get(&format!("/api/browse?path={}%2Fway-out", enc(&run)), &auth).0,
        403
    );
    assert_eq!(get("/api/browse?path=%2Fetc", &auth).0, 403);
    let listing = get(&format!("/api/browse?path={}", enc(&run)), &auth).1;
    assert!(!listing.contains("way-out"), "{listing}");
    for path in [
        outside.join("secret.log"),
        run.join("way-out/secret.log"),
        run.join("../outside"),
    ] {
        let body = format!("{{\"paths\":[\"{}\"]}}", path.display());
        assert_eq!(post("/api/ingest", &body).0, 403, "{body}");
    }

    // The query box.
    assert_eq!(
        post("/api/query", "{\"sql\":\"select count(*) from packets\"}").0,
        200
    );
    for sql in [
        "delete from packets",
        "select 1; delete from packets",
        "attach database 'x' as y",
    ] {
        assert_eq!(
            post("/api/query", &format!("{{\"sql\":\"{sql}\"}}")).0,
            400,
            "{sql}"
        );
    }
    let (_, n) = post("/api/query", "{\"sql\":\"select count(*) from packets\"}");
    assert!(n.contains("[[1082]]"), "{n}");

    // Malformed requests get an answer, not a hang or a crash.
    assert_eq!(http(port, "BREW / HTTP/1.1\r\n\r\n").0, 405);
    assert_eq!(
        http(port, "GET / HTTP/1.1\r\nHost: a\r\nHost: b\r\n\r\n").0,
        400
    );
    assert_eq!(get("/api/runs", &auth).0, 200);
}

#[test]
fn ingest_through_the_page_and_again_after_the_configuration_changes() {
    let scratch = Scratch::new();
    let run = scratch.demo();
    // Start with no configuration at all.
    let config = run.join("packetlane.toml");
    let aside = scratch.0.join("packetlane.toml");
    fs::rename(&config, &aside).unwrap();

    let db = scratch.0.join("store.db");
    let server = Server::bind(Options {
        db: db.clone(),
        roots: vec![run.clone()],
        config: None,
        user_config: None,
        port: 0,
    })
    .unwrap();
    let (port, token) = (server.port(), server.token().to_string());
    std::thread::spawn(move || server.run());
    let auth = format!("X-Packetlane-Token: {token}\r\n");
    let get = |target: &str| {
        http(
            port,
            &format!("GET {target} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{auth}\r\n"),
        )
    };
    let ingest = || {
        let body = format!("{{\"paths\":[\"{}\"]}}", run.display());
        http(
            port,
            &format!(
                "POST /api/ingest HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{auth}Content-Length: {}\r\n\r\n{body}",
                body.len()
            ),
        )
    };

    // An empty store lists no runs.
    assert_eq!(get("/api/runs"), (200, "{\"runs\":[]}".to_string()));

    let (status, body) = ingest();
    assert_eq!(status, 200, "{body}");
    assert!(
        body.contains("\"reread\":false") && body.contains("\"status\":\"ingested\""),
        "{body}"
    );
    let (_, runs) = get("/api/runs");
    assert!(
        runs.contains(&format!("\"root\":\"{}\"", run.display())),
        "{runs}"
    );
    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();
    assert_eq!(count(&reader, "select count(*) from packets"), 1082);
    // Without configuration there is no packet time and no packet names.
    assert_eq!(count(&reader, "select count(packet_ns) from packets"), 0);
    assert!(!get("/api/run?run=1").1.contains("PAYLOAD_SCIENCE"));

    // The same request again changes nothing.
    let (_, body) = ingest();
    assert!(!body.contains("\"status\":\"ingested\""), "{body}");
    assert_eq!(count(&reader, "select count(*) from packets"), 1082);

    // With the configuration in place the run is read afresh, once.
    fs::rename(&aside, &config).unwrap();
    let (status, body) = ingest();
    assert_eq!(status, 200, "{body}");
    assert!(body.contains("\"reread\":true"), "{body}");
    assert_eq!(count(&reader, "select count(*) from packets"), 1082);
    assert_eq!(count(&reader, "select count(packet_ns) from packets"), 1077);
    assert_eq!(count(&reader, "select count(*) from runs"), 1);
    assert!(get("/api/run?run=1").1.contains("PAYLOAD_SCIENCE"));
    let (_, body) = ingest();
    assert!(
        body.contains("\"reread\":false") && !body.contains("\"status\":\"ingested\""),
        "{body}"
    );

    // A configuration that cannot be used is refused with its reason.
    fs::write(&config, "[[packet]]\napid = 4096\nname = \"X\"\n").unwrap();
    let (status, body) = ingest();
    assert_eq!(status, 400);
    assert!(body.contains("0 to 2047"), "{body}");
    assert_eq!(count(&reader, "select count(*) from packets"), 1082);
}

#[test]
fn two_emitters_on_one_apid_are_traced_to_the_logs_that_hold_their_packets() {
    use packetlane::pure::synth::{Cosmos5Writer, Source, cosmos4_entry, cosmos4_header};

    // Two units each log what they send; a collector logs what it receives
    // from both. The second unit uses the first one's APID by mistake.
    let mut first = Source::new(300, 9000, 8);
    let mut second = Source::new(300, 12, 8);
    let mut log_a = Cosmos5Writer::magic();
    let mut writer_a = Cosmos5Writer::new();
    let mut log_b = cosmos4_header(true, "test", "unit-b");
    let mut log_c = Cosmos5Writer::magic();
    let mut writer_c = Cosmos5Writer::new();
    for i in 0..40i64 {
        let t = 1_767_225_600_000_000_000 + i * 1_000_000_000;
        let packet = first.emit();
        log_a.extend(writer_a.entry(t, "A", "DATA", &packet, false));
        log_c.extend(writer_c.entry(t + 1_000_000, "C", "DATA", &packet, false));
        if i >= 10 {
            let packet = second.emit();
            let t = t + 500_000_000;
            log_b.extend(cosmos4_entry(t, "B", "DATA", &packet));
            log_c.extend(writer_c.entry(t + 1_000_000, "C", "DATA", &packet, false));
        }
    }
    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    for (rel, bytes) in [
        ("unit-a/a.bin", log_a),
        ("unit-b/b.bin", log_b),
        ("collector/c.bin", log_c),
    ] {
        let path = run.join(rel);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, bytes).unwrap();
    }

    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();
    let text = |sql: &str| {
        reader.query_user(sql, 10).unwrap().rows[0][0]
            .text()
            .unwrap()
            .to_string()
    };

    // Each unit's own log is clean; the collector's shows two counters.
    assert_eq!(
        count(
            &reader,
            "select count(*) from findings where file_id is not null"
        ),
        1
    );
    assert_eq!(
        text(
            "select l.source from findings x join lanes l on l.id = x.lane_id where x.kind = 'interleaved'"
        ),
        "collector"
    );
    // The packets are traced to the two logs that hold copies of them.
    assert!(
        text("select message from findings where kind = 'origins'")
            .ends_with("unit-a (40), unit-b (30)")
    );
    // And each unit's log lacks the other's packets.
    assert_eq!(
        count(
            &reader,
            "select count(*) from findings where kind = 'hop_missing'"
        ),
        2
    );
}

#[test]
fn files_are_known_by_their_place_in_the_run() {
    use packetlane::pure::synth::Source;
    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    let mut source = Source::new(100, 0, 8);
    let capture: Vec<u8> = (0..20).flat_map(|_| source.emit()).collect();
    for rel in ["unit-a/pass.bin", "collector/pass.bin"] {
        fs::create_dir_all(run.join(rel).parent().unwrap()).unwrap();
        fs::write(run.join(rel), &capture).unwrap();
    }
    fs::write(run.join("unit-a/notes.gz"), [0x1F, 0x8B, 8, 0]).unwrap();
    fs::write(run.join("unit-a/empty.bin"), []).unwrap();

    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();
    let ingest = |store: &mut Store| {
        ingest_targets(store, std::slice::from_ref(&run), None, None, None).unwrap()
    };
    let status = |summary: &packetlane::shell::store::IngestSummary, rel: &str| {
        summary.files.iter().find(|f| f.rel == rel).unwrap().status
    };

    // Two hosts holding the same bytes are two files, not one.
    let first = ingest(&mut store);
    assert_eq!(status(&first, "unit-a/pass.bin"), Status::Ingested);
    assert_eq!(status(&first, "collector/pass.bin"), Status::Ingested);
    assert_eq!(count(&reader, "select count(*) from packets"), 40);
    assert_eq!(
        count(&reader, "select count(distinct source) from packet_view"),
        2
    );

    // Files that could not be read are not recorded as ingested.
    assert_eq!(count(&reader, "select count(*) from files"), 2);
    let second = ingest(&mut store);
    assert_eq!(status(&second, "unit-a/notes.gz"), Status::NotReadable);
    assert_eq!(status(&second, "unit-a/empty.bin"), Status::NotReadable);
    assert_eq!(status(&second, "unit-a/pass.bin"), Status::AlreadyIngested);

    // A log that has grown replaces what was read from it before.
    let mut grown = capture.clone();
    grown.extend((0..5).flat_map(|_| source.emit()));
    fs::write(run.join("unit-a/pass.bin"), &grown).unwrap();
    let third = ingest(&mut store);
    assert_eq!(status(&third, "unit-a/pass.bin"), Status::Ingested);
    assert_eq!(
        status(&third, "collector/pass.bin"),
        Status::AlreadyIngested
    );
    assert_eq!(count(&reader, "select count(*) from packets"), 45);
    assert_eq!(count(&reader, "select count(*) from files"), 2);
    assert_eq!(
        count(&reader, "select count(*) from lanes where count = 25"),
        1
    );
}

#[test]
fn a_query_cannot_ask_for_an_enormous_result() {
    let scratch = Scratch::new();
    let db = scratch.0.join("store.db");
    drop(Store::open(&db).unwrap());
    let reader = Store::open_read_only(&db, Duration::from_secs(5)).unwrap();
    assert!(
        reader
            .query_user("select printf('%10000000s', 'x')", 10)
            .is_err()
    );
    let many = "with recursive r(n) as (select 1 union all select n + 1 from r where n < 100)
                select printf('%900000s', 'x') from r";
    assert!(reader.query_user(many, 1000).is_err());
    assert!(
        reader
            .query_user("select printf('%1000s', 'x')", 10)
            .is_ok()
    );
}

#[test]
fn pre_counted_and_direct_density_agree() {
    use packetlane::pure::sql::{self, Clock};
    let scratch = Scratch::new();
    let run = scratch.demo();
    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();

    let t0 = 1_767_225_600_000_000_000i64;
    let total = |queries: Vec<sql::Query>| -> i64 {
        queries
            .iter()
            .flat_map(|q| reader.query(q, 100_000).unwrap().rows)
            .map(|r| r[2].int().unwrap())
            .sum()
    };
    for clock in [Clock::Receive, Clock::Packet] {
        let meta = reader.query(&sql::coarse_meta(1, clock), 1).unwrap();
        let coarse = Some((
            meta.rows[0][0].int().unwrap(),
            meta.rows[0][1].int().unwrap(),
        ));
        for (from, to, buckets) in [
            (t0 - 5_000_000_000, t0 + 70_000_000_000, 400),
            (t0, t0 + 59_999_999_999, 7),
            (t0 + 1_234_567_891, t0 + 31_234_567_890, 3),
            (t0 + 10_000_000_001, t0 + 10_030_000_000, 1),
            (t0 + 20_000_000_000, t0 + 20_000_000_000, 5),
        ] {
            let with = total(sql::density(1, clock, from, to, buckets, coarse));
            let without = total(sql::density(1, clock, from, to, buckets, None));
            assert_eq!(with, without, "{clock:?} {from}..{to} in {buckets}");
        }
    }
}

#[test]
fn the_server_serves_nothing_from_outside_its_folders() {
    let scratch = Scratch::new();
    let run = scratch.demo();
    // The store holds a run from one place; the server is given another.
    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    drop(store);
    let parent = scratch.0.join("parent");
    for (dir, name) in [("a", "x.log"), ("b", "y.log")] {
        fs::create_dir_all(parent.join(dir)).unwrap();
        fs::write(parent.join(dir).join(name), "2026-01-01 00:00:00 line\n").unwrap();
    }
    // A configuration file that sits above both roots, outside each of them.
    fs::write(
        parent.join("packetlane.toml"),
        "[[packet]]\napid = 1\nname = \"FROM_OUTSIDE\"\n",
    )
    .unwrap();

    let server = Server::bind(Options {
        db: db.clone(),
        roots: vec![parent.join("a"), parent.join("b")],
        config: None,
        user_config: None,
        port: 0,
    })
    .unwrap();
    let (port, token) = (server.port(), server.token().to_string());
    std::thread::spawn(move || server.run());
    let auth = format!("X-Packetlane-Token: {token}\r\n");
    let get = |target: &str| {
        http(
            port,
            &format!("GET {target} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{auth}\r\n"),
        )
    };
    let post = |body: &str| {
        http(
            port,
            &format!(
                "POST /api/ingest HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\n{auth}Content-Length: {}\r\n\r\n{body}",
                body.len()
            ),
        )
    };

    // A packet from the other run: its details are known, its bytes are not served.
    let (status, body) = get("/api/packet?id=1");
    assert_eq!(status, 200);
    assert!(
        body.contains("\"hex\":null") && body.contains("outside the allowed folders"),
        "{body}"
    );

    // Items from two roots would make their shared parent the run folder.
    let both = format!(
        "{{\"paths\":[\"{}\",\"{}\"]}}",
        parent.join("a/x.log").display(),
        parent.join("b/y.log").display()
    );
    let (status, body) = post(&both);
    assert!(status == 400 || status == 403, "{status} {body}");
    let reader = Store::open_read_only(&db, Duration::from_secs(10)).unwrap();
    assert_eq!(count(&reader, "select count(*) from runs"), 1);
    assert_eq!(
        count(
            &reader,
            "select count(*) from runs where config like '%FROM_OUTSIDE%'"
        ),
        0
    );
    // One root at a time is fine.
    let one = format!("{{\"paths\":[\"{}\"]}}", parent.join("a").display());
    assert_eq!(post(&one).0, 200);

    // Missing and present paths outside the roots get the same answer.
    let present = get("/api/browse?path=%2Fetc%2Fpasswd").0;
    let missing = get("/api/browse?path=%2Fetc%2Fno-such-file-here").0;
    assert_eq!((present, missing), (403, 403));
}

/// A file of CADUs is recognised by its sync markers, read with the frame
/// layout from the configuration, and stored as the packets inside it.
#[test]
fn a_file_of_cadus_is_ingested_as_its_packets() {
    use packetlane::pure::config::Config;
    use packetlane::pure::synth::{Source, demo_cadus};

    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    fs::create_dir_all(run.join("station")).unwrap();
    let toml = "[frames]\nrandomized = true\ncrc = true\nrs_parity_bytes = 32\n";
    fs::write(run.join("packetlane.toml"), toml).unwrap();
    let mut a = Source::new(0x1A3, 0, 5);
    let mut b = Source::new(0x0B0, 0, 300);
    let packets: Vec<u8> = (0..40)
        .flat_map(|_| [a.emit(), b.emit()].concat())
        .collect();
    let params = Config::parse(toml).unwrap().frame_params(256);
    fs::write(run.join("station/pass.cadu"), demo_cadus(&params, &packets)).unwrap();

    let mut store = Store::open(&scratch.0.join("store.db")).unwrap();
    let summary = ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    let file = summary
        .files
        .iter()
        .find(|f| f.rel == "station/pass.cadu")
        .unwrap();
    assert_eq!(file.status, Status::Ingested);
    assert_eq!(file.packets, 80, "{}", file.note);
    assert_eq!(
        file.note,
        "TM frames in 256-byte CADUs, randomised, CRC, 32 check bytes"
    );
    assert_eq!(
        count(&store, "SELECT COUNT(*) FROM files WHERE format = 'cadu'"),
        1
    );
    assert_eq!(
        count(&store, "SELECT COUNT(*) FROM packets WHERE apid = 419"),
        40
    );

    // The wrong layout is reported, not read as an empty file.
    fs::write(run.join("packetlane.toml"), "[frames]\nkind = \"aos\"\n").unwrap();
    let summary = ingest_targets(&mut store, &[run], None, None, None).unwrap();
    let file = summary
        .files
        .iter()
        .find(|f| f.rel == "station/pass.cadu")
        .unwrap();
    assert_eq!(file.packets, 0);
    assert!(file.note.contains("AOS frame version"), "{}", file.note);
}

/// A log as COSMOS 4.2 wrote it is ingested, and what it says about itself
/// is kept next to why reading stopped.
#[test]
fn a_cosmos2_log_is_ingested_and_described() {
    use packetlane::pure::synth::{Source, cosmos2_entry, cosmos2_header};

    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    fs::create_dir_all(run.join("gse")).unwrap();
    let mut meta = vec![1u8];
    meta.extend_from_slice(b"FLATSAT_A");
    meta.resize(33, 0);
    meta.extend_from_slice(b"4.2.4");
    meta.resize(123, 0);
    let mut src = Source::new(0x1A3, 0, 5);
    let mut data = cosmos2_header(true, "FLATSAT_A", "gse-01");
    data.extend(cosmos2_entry(
        1_700_000_000_000_000_000,
        "SYSTEM",
        "META",
        &meta,
    ));
    for i in 0..10 {
        let t = 1_700_000_001_000_000_000 + i * 1_000_000_000;
        data.extend(cosmos2_entry(t, "SIM", "HK", &src.emit()));
    }
    data.truncate(data.len() - 3);
    fs::write(run.join("gse/2023_11_14_22_13_20_tlm.bin"), data).unwrap();

    let mut store = Store::open(&scratch.0.join("store.db")).unwrap();
    let summary = ingest_targets(&mut store, &[run], None, None, None).unwrap();
    let file = &summary.files[0];
    assert_eq!(file.status, Status::Ingested);
    assert_eq!(file.format, "cosmos2");
    assert_eq!(file.packets, 10); // META and nine whole packets
    assert!(
        file.note
            .starts_with("COSMOS config FLATSAT_A on gse-01, version 4.2.4; Truncated"),
        "{}",
        file.note
    );
    assert_eq!(
        count(&store, "SELECT COUNT(*) FROM packets WHERE apid = 419"),
        9
    );
}

/// Starts a server over `db` and returns a function that GETs an API path
/// and parses the JSON reply.
fn serve(db: PathBuf, root: PathBuf) -> impl Fn(&str) -> serde_json::Value {
    let server = Server::bind(Options {
        db,
        roots: vec![root],
        config: None,
        user_config: None,
        port: 0,
    })
    .unwrap();
    let (port, token) = (server.port(), server.token().to_string());
    std::thread::spawn(move || server.run());
    move |target: &str| {
        let (status, body) = http(
            port,
            &format!(
                "GET {target} HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nX-Packetlane-Token: {token}\r\n\r\n"
            ),
        );
        assert_eq!(status, 200, "{target}: {body}");
        serde_json::from_str(&body).unwrap()
    }
}

/// A packet in a CADU file is not a run of bytes in that file: it is spread
/// over frames and may be randomised. The packet view must still show it.
#[test]
fn packets_inside_cadus_can_be_read_back() {
    use packetlane::pure::config::Config;
    use packetlane::pure::format::hex;
    use packetlane::pure::synth::{Source, demo_cadus};

    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    fs::create_dir_all(run.join("station")).unwrap();
    let toml = "[frames]\nrandomized = true\ncrc = true\nrs_parity_bytes = 32\n";
    fs::write(run.join("packetlane.toml"), toml).unwrap();
    let mut a = Source::new(0x1A3, 0, 5);
    let mut b = Source::new(0x0B0, 0, 700);
    let packets: Vec<Vec<u8>> = (0..12).flat_map(|_| [a.emit(), b.emit()]).collect();
    let params = Config::parse(toml).unwrap().frame_params(256);
    let mut file = vec![0x55u8; 100]; // the capture starts mid-frame
    file.extend(demo_cadus(&params, &packets.concat()));
    fs::write(run.join("station/pass.cadu"), file).unwrap();

    let db = scratch.0.join("store.db");
    let mut store = Store::open(&db).unwrap();
    ingest_targets(&mut store, std::slice::from_ref(&run), None, None, None).unwrap();
    let ids = store
        .query_user("SELECT id FROM packets ORDER BY idx", 100)
        .unwrap();
    assert_eq!(ids.rows.len(), packets.len());
    drop(store);

    let get = serve(db, run);
    for (row, packet) in ids.rows.iter().zip(&packets) {
        let body = get(&format!("/api/packet?id={}", row[0].int().unwrap()));
        assert_eq!(body["error"], serde_json::Value::Null, "{body}");
        let shown = &packet[..packet.len().min(body["hex"].as_str().unwrap().len() / 2)];
        assert_eq!(body["hex"], hex(shown));
    }
}

/// Damage a CADU decoder reads past is stored as findings, not swallowed.
#[test]
fn frames_lost_from_a_cadu_file_become_findings() {
    use packetlane::pure::config::Config;
    use packetlane::pure::synth::{Source, demo_cadus};

    let scratch = Scratch::new();
    let run = scratch.0.join("run");
    fs::create_dir_all(run.join("station")).unwrap();
    let toml = "[frames]\ncrc = true\n";
    fs::write(run.join("packetlane.toml"), toml).unwrap();
    let mut src = Source::new(0x1A3, 0, 40);
    let packets: Vec<u8> = (0..60).flat_map(|_| src.emit()).collect();
    let mut file = demo_cadus(&Config::parse(toml).unwrap().frame_params(128), &packets);
    file.drain(5 * 128..7 * 128); // two frames gone
    file[10 * 128 + 50] ^= 1; // one fails its CRC
    fs::write(run.join("station/pass.cadu"), file).unwrap();

    let mut store = Store::open(&scratch.0.join("store.db")).unwrap();
    ingest_targets(&mut store, &[run], None, None, None).unwrap();
    let found = store
        .query_user(
            "SELECT kind, severity, message FROM findings ORDER BY id",
            50,
        )
        .unwrap();
    let kinds: Vec<&str> = found.rows.iter().map(|r| r[0].text().unwrap()).collect();
    assert!(kinds.contains(&"frame_gap"), "{kinds:?}");
    assert!(kinds.contains(&"bad_frame"), "{kinds:?}");
    // The packets that were in those frames also show as sequence gaps.
    assert!(kinds.contains(&"gap"), "{kinds:?}");
    let gap = found
        .rows
        .iter()
        .find(|r| r[0].text() == Some("frame_gap"))
        .unwrap();
    assert_eq!(gap[1].text(), Some("problem"));
    assert!(
        gap[2].text().unwrap().contains("2 frames missing"),
        "{:?}",
        gap[2]
    );
}

